  function injectSettingsTemplates() {
    Object.entries(SETTINGS_TEMPLATES).forEach(([id, html]) => {
      if (!document.getElementById(id)) {
        const t = document.createElement("template");
        t.id = id;
        t.innerHTML = html.trim();
        document.body.appendChild(t);
      }
    });
  }

